ee:variables.ee:set-variable:
%dw 2.0 output application/java
var agendada = vars.req.scheduledDate as Date var recorrencia = (vars.req.recurrence default "UNICA") as String
// Próxima execução depois da primeira var proxima = if (recorrencia == "SEMANAL") agendada + |P7D| else if (recorrencia == "MENSAL") agendada + |P1M| else null --- { scheduleId: ((now() as Number) mod 900000) + 100000, customerId: vars.req.customerId, sourceAccountId: vars.req.sourceAccountId, destinationAccountId: vars.req.destinationAccountId, amount: (vars.req.amount default 0) as Number, description: vars.req.description default null, scheduledDate: agendada as String, recurrence: recorrencia, endDate: if (isEmpty(vars.req.endDate)) null else (vars.req.endDate as Date) as String, nextExecutionDate: agendada as String, proximaAposEsta: if (proxima == null) null else (proxima as String), status: "AGENDADA", createdAt: now() as String }

