wsc:message.wsc:body:
#[%dw 2.0
output application/xml
ns prc http://example.com/banking/process
---
{
  prc#transferFundsRequest: {
    prc#contaOrigem:  vars.req.sourceAccountId,
    prc#contaDestino: vars.req.destinationAccountId,
    prc#valor:        vars.req.amount,
    (prc#descricao:   vars.req.description) if (vars.req.description != null)
  }
}]

ee:message.ee:set-payload:
%dw 2.0
output application/java

var r     = payload.body.transferFundsResponse
var st    = r.status as String
var risco = r.riskFlag as String
var valor = vars.req.amount as Number

var texto = {
  "CONFIRMADA": "Transferência de " ++ (valor as String {format: "#,##0.00"})
             ++ " AOA processada com sucesso. Referência: "
             ++ (r.transactionId default "-"),
  "PENDENTE": "A sua transferência está em análise de segurança."
}[st] default "Operação não concluída."

var alerta =
  if (st == "ALTO")
    "Destinatário pouco ou nunca utilizado e valor elevado."
  else if (risco == "MEDIO")
    "TDestinatário já utilizado anteriormente. Valor dentro de um padrão razoável."
  else
    "Destinatário habitual. Transferência compatível com o seu histórico."
---
{
  body: {
    makeTransferResponse: {
      status:     st,
      message:    texto,
      newBalance: r.novoSaldo as Number,
      riskFlag:   risco,
      (alertMessage: alerta) if (risco != "BAIXO" or st == "PENDENTE_REVISAO")
    }
  } write "application/xml"
}

wsc:message.wsc:body:
#[%dw 2.0
output application/xml
ns prc http://example.com/banking/process
---
{
  prc#getEnrichedStatementRequest: {
    prc#accountId:  vars.req.accountId as String,
    prc#dataInicio: vars.req.startDate as String,
    prc#dataFim:    vars.req.endDate as String
  }
}]

ee:message.ee:set-payload:
%dw 2.0

output application/java
var movs  = (payload.body..*transactionDetails) default []
var conta = vars.req.accountId as String

fun ehDebito(m)  = (m.sourceAccount as String) == conta
fun descricao(m) = if (isEmpty(m.description))
                     ("Movimento " ++ (m.transactionId default ""))
                   else (m.description as String)
---
{
  body: {
    viewStatementResponse: {
	transactions:{
		((movs orderBy ($.transactionDate as DateTime)) map (m) -> {
        transaction: {
          transactionId:   (m.transactionId as Number) default 0,
          transactionDate: m.transactionDate as LocalDateTime,
          description:     descricao(m),
          category:        (m.category default "OUTROS"),
          amount:          m.amount as Number,
          destinationAccount: m.destinationAccount default "-",
          "type":          if (ehDebito(m)) "DEBITO" else "CREDITO"
        }
      })
	}

    }
  } write "application/xml"
}

wsc:message.wsc:body:
#[%dw 2.0
output application/xml
ns prc http://example.com/banking/process
---
{
  prc#getSpendingInsightsRequest: {
    prc#customerId: vars.customerId
  }
}]

ee:message.ee:set-payload:
%dw 2.0
output application/java
ns web http://standardbank.ao/internetbanking/experience/1.0
var nomes = {
  "transporte": "transporte", "taxi": "táxi", "alimentacao": "alimentação",
  "pagamento": "pagamentos", "lazer": "lazer", "saude": "saúde",
  "outros": "outros", "unknown": "categoria desconhecida"
}

var insights = (payload.body..*insight) default []
var blocos   = (payload.body..*percentualVariacao default []) filter ($ is Object)

fun kz(n)     = (((n default 0) as Number) as String {format: "#,##0.00"}) ++ " Kz"
fun pct(n)    = abs((n default 0) as Number) as String {format: "0.#"}
fun nome(k)   = nomes[k] default k
fun codigo(k) = if (k == "unknown") "Categoria Desconhecida" else upper(k)

var categorias = flatten(
  blocos map ((pv) ->
    pv pluck ((v, k) -> {
      chave:      k as String,
      atual:      (v.atual default 0) as Number,
      anterior:   (v.anterior default 0) as Number,
      // <percentual/> vazio chega como null ou "" — o isEmpty cobre os dois
      percentual: if (isEmpty(v.percentual)) null else (v.percentual as Number)
    })
  )
) orderBy -($.atual)

fun mensagem(c) =
  if (c.atual == 0 and c.anterior > 0)
    "Não teve gastos em " ++ nome(c.chave) ++ " este mês (no mês passado: " ++ kz(c.anterior) ++ ")."
  else if (c.percentual == null)
    "Novo este mês: gastou " ++ kz(c.atual) ++ " em " ++ nome(c.chave) ++ "."
  else if (c.percentual >= 200)
    "Os seus gastos em " ++ nome(c.chave) ++ " subiram de " ++ kz(c.anterior) ++ " para " ++ kz(c.atual) ++ " este mês."
  else if (c.percentual <= -99)
    "Praticamente deixou de gastar em " ++ nome(c.chave) ++ " este mês."
  else if (c.percentual < 0 )
    "Boa notícia: gastou " ++ pct(c.percentual) ++ "% menos em " ++ nome(c.chave) ++ " face ao mês passado."
  else if (c.percentual > 0)
    "Gastou " ++ pct(c.percentual) ++ "% mais em " ++ nome(c.chave) ++ " do que no mês passado."
  else if (c.percentual == 0)
    "Gastou mais em " ++ nome(c.chave) ++ " do que no mês passado."
  else
    "Gastos em " ++ nome(c.chave) ++ " iguais aos do mês passado: " ++ kz(c.atual) ++ "."
---
{
  body: {
    web#viewSpendingInsightsResponse: {
       (
       	insights map (i) -> {
          title: i.categoria,
          description:  i.mensagem default ""
		}
		),
        insights:{
	      (categorias map (c) -> {
	        web#insight: {
	          category: upper(codigo(c.chave)),
	          currentMonth: c.atual default "-",
	          lastMonth: c.anterior default "-",
	          message:  mensagem(c),
	          (changePercentage: c.percentual) if (c.percentual != null)
	        }
	      })
      }
    }
  } write "application/xml"
}

