ee:message.ee:set-payload:
%dw 2.0
output application/java
ns web http://standardbank.ao/internetbanking/experience/1.0

var req    = payload.body.manageCardResponse
var cardId = req.cardId
var accao  = req.status
---
{
  body: {
    web#blockOrUnblockCardResponse: {
      web#cardId: cardId,
      web#status: accao,
      web#message:
        if (accao == "BLOQUEADO")
          "Cartao bloqueado. Pode desbloquea-lo a qualquer momento na app."
        else if (accao == "CANCELADO")
          "Cartao cancelado. Não pode utilizar na app."
        else
          "Cartao ativo e pronto a usar."
    }
  } write "application/xml"
}

