wsc:message.wsc:body:
#[%dw 2.0
output application/xml
ns prc http://example.com/banking/process
---
{
  prc#getEnrichedStatementRequest: {
    prc#accountId:  vars.req.accountId as String,
    prc#dataInicio: vars.req.startDate as String,
    prc#dataFim:    vars.req.endDate as String
  }
}]

ee:message.ee:set-payload:
%dw 2.0
output application/java
ns web http://standardbank.ao/internetbanking/experience/1.0
import toBase64 from dw::core::Binaries

var movs  = (payload.body..*transactionDetails) default []
var conta = (vars.req.accountId default "") as String

fun dataMov(m)  = (m.transactionDate default "") as LocalDateTime
fun ehDebito(m) = ((m.sourceAccount default "") as String) == conta

// mais recente primeiro
var ordenados = if (isEmpty(movs)) [] else (movs orderBy dataMov($))[-1 to 0]

var linhas = ordenados map (m) -> {
  Data:      dataMov(m) as String {format: "dd/MM/yyyy HH:mm"},
  Descricao: if (isEmpty(m.description)) ("Movimento " ++ ((m.transactionId default "") as String)) else (m.description as String),
  Categoria: if (isEmpty(m.category)) "OUTROS" else upper(m.category as String),
  Tipo:      if (ehDebito(m)) "DEBITO" else "CREDITO",
  Valor: do {
    var v = abs((m.amount default 0) as Number)
    var s = if (ehDebito(m)) -v else v
    ---
    (s as String {format: "0.00"}) replace "." with ","
  }
}

var csv = write(linhas, "application/csv", {separator: ";", header: true})
---
{
  body: {
    web#exportStatementResponse: {
      web#fileName:    "extracto-" ++ conta ++ "-" ++ (now() as String {format: "yyyyMMdd"}) ++ ".csv",
      web#mimeType:    "text/csv",
      web#fileContent: toBase64(csv as Binary)
    }
  } write "application/xml"
}
